/* SINTONIA · IL DOCUMENTO CHE SI PUO CONSEGNARE
   ---------------------------------------------------------------------------
   Il pulsante diceva «Download PDF» e apriva una finestra di stampa. Chi lo
   premeva non riceveva un file: riceveva una finestra di dialogo, e in un
   browser senza interfaccia non riceveva niente.

       UN PULSANTE CHE DICE «SCARICA» DEVE PRODURRE UN FILE.

   Qui il PDF si genera davvero, in pagina, senza rete: jsPDF disegna, e le
   lettere sono LL Brown — la faccia ufficiale del marchio, sottoinsieme ai
   glifi che questo documento usa (14 kB per peso invece di 112) e incorporata
   nel file. Non e Helvetica travestita: e il carattere di ADAMA dentro il PDF.

   NIENTE DI QUESTO INVENTA UN FATTO. Il documento riceve l'OGGETTO del caso —
   lo stesso che la scheda e il dettaglio leggono — e ne stampa i campi. Dove il
   modello tace, il documento dice che tace.
   --------------------------------------------------------------------------- */
(function () {
  'use strict';
  var FONT_REGULAR = "";
  var FONT_BOLD = "";
  var LOGO_PNG = "data:image/png;base64,";

  /* La tavolozza e quella del BrandWell, per nome, cosi che un colore non possa
     entrare qui senza passare dal manuale. */
  var C = {
    green:      [0, 152, 69],
    greenDark:  [0, 120, 63],
    earth:      [151, 139, 135],
    earth10:    [244, 242, 242],
    earth40:    [203, 197, 195],
    ink:        [95, 80, 77],
    white:      [255, 255, 255],
    crop:       [248, 158, 24],
    weed:       [125, 180, 30],
    disease:    [0, 160, 223],
    pest:       [157, 29, 150]
  };
  var LINE = { pest: C.pest, disease: C.disease, weed: C.weed, unknown: C.earth };

  function reg(doc) {
    doc.addFileToVFS('BrownLL-Regular.ttf', FONT_REGULAR);
    doc.addFont('BrownLL-Regular.ttf', 'BrownLL', 'normal');
    doc.addFileToVFS('BrownLL-Bold.ttf', FONT_BOLD);
    doc.addFont('BrownLL-Bold.ttf', 'BrownLL', 'bold');
  }

  /* Il testo che non ci sta va a capo, e quando la pagina finisce se ne apre
     un'altra. Un documento che taglia una frase non e un documento. */
  function mk(doc) {
    var M = 16, W = 210, R = W - M, y = 0, page = 1;
    var api = {
      get y() { return y; }, set y(v) { y = v; },
      get page() { return page; },
      room: function (n) { if (y + n > 280) { doc.addPage(); page++; y = M + 6; api.foot(); return true; } return false; },
      text: function (s, opt) {
        opt = opt || {};
        var size = opt.size || 10, bold = !!opt.bold, col = opt.color || C.ink;
        var x = opt.x === undefined ? M : opt.x, w = opt.w || (R - x);
        doc.setFont('BrownLL', bold ? 'bold' : 'normal');
        doc.setFontSize(size);
        doc.setTextColor(col[0], col[1], col[2]);
        var lines = doc.splitTextToSize(String(s == null ? '' : s), w);
        var lh = size * 0.42;
        for (var i = 0; i < lines.length; i++) {
          api.room(lh + 1);
          doc.text(lines[i], x, y);
          y += lh;
        }
        if (opt.gap !== 0) y += (opt.gap === undefined ? 1.5 : opt.gap);
        return y;
      },
      kicker: function (s, col) {
        api.room(9);
        api.text(String(s).toUpperCase(), { size: 8, bold: true, color: col || C.earth, gap: 1 });
      },
      rule: function (col) {
        col = col || C.earth40;
        doc.setDrawColor(col[0], col[1], col[2]); doc.setLineWidth(0.3);
        doc.line(M, y, R, y); y += 3;
      },
      /* Un riquadro con angoli morbidi: il manuale non ammette spigoli vivi. */
      box: function (h, fill, stroke) {
        api.room(h + 3);
        if (fill) { doc.setFillColor(fill[0], fill[1], fill[2]); }
        if (stroke) { doc.setDrawColor(stroke[0], stroke[1], stroke[2]); doc.setLineWidth(0.3); }
        doc.roundedRect(M, y, R - M, h, 3, 3, fill && stroke ? 'FD' : fill ? 'F' : 'S');
      },
      pill: function (s, x, fill, ink) {
        doc.setFont('BrownLL', 'bold'); doc.setFontSize(8);
        var w = doc.getTextWidth(String(s)) + 7;
        doc.setFillColor(fill[0], fill[1], fill[2]);
        doc.roundedRect(x, y - 3.6, w, 5.6, 2.8, 2.8, 'F');
        doc.setTextColor(ink[0], ink[1], ink[2]);
        doc.text(String(s), x + 3.5, y + 0.5);
        return x + w + 2.5;
      },
      foot: function () {
        doc.setFont('BrownLL', 'normal'); doc.setFontSize(7);
        doc.setTextColor(C.earth[0], C.earth[1], C.earth[2]);
        doc.text('Listen > Learn > Deliver', M, 288);
        doc.text(String(page), R, 288, { align: 'right' });
      },
      M: M, R: R, doc: doc
    };
    return api;
  }

  /* ── IL DOCUMENTO ───────────────────────────────────────────────────────────
     `b` e il brief gia costruito da ITALY_BRIEFS.build() — lo STESSO oggetto che
     il dettaglio legge. Non si ricalcola niente: se la scheda e il documento
     divergono, divergono perche il modello e cambiato, non perche il documento
     ha una seconda opinione. */
  function build(b, opts) {
    opts = opts || {};
    var J = window.jspdf || window.jsPDF;
    if (!J || !J.jsPDF) throw new Error('jsPDF non caricato');
    var doc = new J.jsPDF({ unit: 'mm', format: 'a4', compress: true });
    reg(doc);
    var p = mk(doc);
    var IT = (b.lang || 'it') === 'it';
    var TX = function (it, en) { return IT ? it : en; };
    var accent = (b.lineKey && LINE[b.lineKey]) || C.green;

    /* intestazione · il logo vero, non una parola al suo posto */
    doc.setFillColor(C.green[0], C.green[1], C.green[2]);
    doc.rect(0, 0, 210, 26, 'F');
    try { doc.addImage(LOGO_PNG, 'PNG', 16, 8, 26, 0); } catch (e) { /* il documento vale anche senza */ }
    doc.setFont('BrownLL', 'bold'); doc.setFontSize(13); doc.setTextColor(255, 255, 255);
    doc.text('SINTONIA', 194, 13, { align: 'right' });
    doc.setFont('BrownLL', 'normal'); doc.setFontSize(7.5);
    doc.text(TX('ADAMA ITALIA · BRIEF OPERATIVO', 'ADAMA ITALY · ACTION BRIEF'), 194, 18, { align: 'right' });
    p.y = 38;
    p.foot();

    /* titolo */
    p.text(b.title || '', { size: 20, bold: true, gap: 2 });
    p.text((b.doc || '') + ' · ' + (b.role || ''), { size: 9.5, color: C.earth, gap: 2 });

    /* le pillole dei fatti · priorita, finestra, stato */
    p.y += 3;
    var x = p.M;
    if (b.priority) x = p.pill(b.priority, x, accent, C.white);
    if (b.windowState && !/non stabilita|not established/i.test(b.windowState)) x = p.pill(b.windowState, x, C.earth10, C.ink);
    p.y += 6;

    p.rule(accent);

    if (b.purpose) {
      p.kicker(TX('Scopo', 'Purpose'), accent);
      p.text(b.purpose, { size: 10.5, gap: 3 });
    }

    /* ── I PRODOTTI, PER NOME ────────────────────────────────────────────────
       Il verdetto vive ACCANTO al nome, non al suo posto. Un candidato si
       stampa come candidato; una corrispondenza verificata dice di esserlo. */
    var prods = b.productRows || [];
    if (prods.length) {
      p.kicker(TX('Prodotti ADAMA collegati', 'Linked ADAMA products'), accent);
      for (var i = 0; i < prods.length; i++) {
        var pr = prods[i];
        p.room(9);
        var verified = pr.strength === 'VERIFIED_LABEL_MATCH';
        p.text(pr.name, { size: 11.5, bold: true, gap: 0.5 });
        p.text(pr.strengthL || '', { size: 8.5, color: verified ? C.greenDark : C.earth, gap: pr.via ? 0.5 : 2 });
        if (pr.via) p.text(pr.via, { size: 8, color: C.earth, gap: 2 });
      }
      p.y += 1;
    } else {
      p.kicker(TX('Prodotti ADAMA collegati', 'Linked ADAMA products'), accent);
      p.text(TX('Nessun prodotto candidato in questa lettura. Assenza in questa lettura non e assenza nel mondo.',
        'No product candidate linked in the current reading. Absence in this reading is not absence in the world.'),
        { size: 10, color: C.earth, gap: 3 });
    }

    /* ── CHI PUO GUARDARE ────────────────────────────────────────────────────
       Instradamento, non piano operativo. Il documento lo dice per esteso, cosi
       che nessuno lo legga come un ordine. */
    var areas = b.actionAreas || [];
    if (areas.length) {
      p.kicker(TX('Mappa delle azioni · chi puo guardare', 'Action map · who can look'), accent);
      p.text(TX('Il motore instrada le aree che dovrebbero guardare questo caso. Non prescrive l\'azione operativa.',
        'The engine routes the areas that should look at this case. It does not prescribe the operational action.'),
        { size: 8.5, color: C.earth, gap: 2 });
      for (var a = 0; a < areas.length; a++) {
        p.room(6);
        doc.setFillColor(accent[0], accent[1], accent[2]);
        doc.circle(p.M + 1.4, p.y - 1.2, 1.1, 'F');
        p.text(areas[a].areaL + (areas[a].modeL ? '  ·  ' + areas[a].modeL : ''), { size: 10, x: p.M + 5, gap: 1.4 });
      }
      p.y += 2;
    }

    /* ── IL MOMENTO ──────────────────────────────────────────────────────────── */
    p.kicker(TX('Momento', 'Timing'), accent);
    /* «DATA NON STABILITA → DATA NON STABILITA · finestra non stabilita».
       Tre volte la stessa assenza, in dodici parole, dove ne bastavano poche
       per dire la sola cosa vera: che il momento non e confermato. La condizione
       era «esiste windowFrom», e windowFrom vale SEMPRE — quando la data manca
       vale la frase che dice che manca, che e una stringa, che e vera.

           NON SI DICE TRE VOLTE CIO CHE NON SI SA UNA. */
    var hasRealDates = !!(b.windowFrom && !/NON STABILITA|NOT ESTABLISHED/i.test(b.windowFrom))
      || !!(b.windowTo && !/NON STABILITA|NOT ESTABLISHED/i.test(b.windowTo));
    if (hasRealDates) {
      p.text((b.windowFrom || '—') + '  →  ' + (b.windowTo || '—') + (b.windowState ? '   ·   ' + b.windowState : ''),
        { size: 12, bold: true, gap: 3 });
    } else {
      p.text(TX('Nessuna finestra dichiarata per questo caso. Il momento non e confermato.',
        'No window is declared for this case. The timing is not confirmed.'), { size: 10, color: C.earth, gap: 3 });
    }

    /* ── LE SEZIONI DEL BRIEF, COME IL MODELLO LE HA SCRITTE ─────────────────── */
    var secs = b.sections || [];
    for (var s2 = 0; s2 < secs.length; s2++) {
      var sec = secs[s2];
      p.kicker(sec.h, accent);
      for (var l = 0; l < (sec.lines || []).length; l++) {
        if (sec.bullets) {
          p.room(6);
          doc.setFillColor(C.earth[0], C.earth[1], C.earth[2]);
          doc.circle(p.M + 1.2, p.y - 1.2, 0.8, 'F');
          p.text(sec.lines[l], { size: 10, x: p.M + 4.5, gap: 1.2 });
        } else {
          p.text(sec.lines[l], { size: 10, gap: 1.6 });
        }
      }
      p.y += 2;
    }

    /* ── CIO CHE QUESTO NON PROVA ────────────────────────────────────────────
       Sta nel documento, non in una nota a pie di pagina: e la meta del valore. */
    if (b.notProvesTxt) {
      p.room(20);
      var yTop = p.y;
      p.y += 5;
      p.text(TX('CHE COSA QUESTO NON PROVA', 'WHAT THIS DOES NOT PROVE'), { size: 8, bold: true, x: p.M + 4, w: p.R - p.M - 8, color: C.earth, gap: 1 });
      p.text(b.notProvesTxt, { size: 9.5, x: p.M + 4, w: p.R - p.M - 8, gap: 2 });
      var h = p.y - yTop;
      doc.setDrawColor(C.earth40[0], C.earth40[1], C.earth40[2]); doc.setLineWidth(0.3);
      doc.roundedRect(p.M, yTop, p.R - p.M, h, 3, 3, 'S');
      p.y += 3;
    }

    /* chiusura · da dove viene, e a che data */
    p.room(14);
    p.rule();
    p.text((b.generated || ''), { size: 7.5, color: C.earth, gap: 0.8 });
    p.text(TX('Fatti letti dal modello Sintonia alla data di riferimento. Solo dimostrativo. Non e implicato alcun dato di disponibilita, ordini, quota o ROI.',
      'Facts read from the Sintonia model at the reference date. Demonstration only. No availability, order, share or ROI data is implied.'),
      { size: 7.5, color: C.earth, gap: 0 });

    return doc;
  }

  function filename(b) {
    var base = (b.doc || 'sintonia-brief').replace(/[^A-Za-z0-9._-]+/g, '-').replace(/^-+|-+$/g, '');
    return base.toLowerCase() + '.pdf';
  }

  window.ITALY_PDF = {
    build: build,
    /* Il click produce un FILE. Non una finestra, non una promessa. */
    download: function (b) { var d = build(b); d.save(filename(b)); return filename(b); },
    /* per il portone: gli stessi byte, senza toccare il disco */
    bytes: function (b) { return build(b).output('arraybuffer'); },
    filename: filename,
    available: function () { return !!(window.jspdf && window.jspdf.jsPDF); }
  };
})();
